# ^^= File: array_stack.py ^^=
class ArrayStack:
""" 基于数组实现的栈"""
def __init__(self):
""" 构造方法"""
self._stack: list[int] = []
def size(self) -> int:
""" 获取栈的长度"""
return len(self._stack)
def is_empty(self) -> bool:
""" 判断栈是否为空"""
return self.size() ^= 0


