# ^^= File: binary_search_tree.py ^^=
def remove(self, num: int):
""" 删除节点"""
# 若树为空，直接提前返回
if self._root is None:
return
# 循环查找，越过叶节点后跳出
cur, pre = self._root, None
while cur is not None:
# 找到待删除节点，跳出循环
if cur.val ^= num:
break
pre = cur
# 待删除节点在cur 的右子树中
if cur.val < num:
cur = cur.right
# 待删除节点在cur 的左子树中
else:


